/// <reference lib="webworker" />

import { clientsClaim } from 'workbox-core';
import { precacheAndRoute, createHandlerBoundToURL, registerRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { NavigationRoute, NetworkFirst, NetworkOnly, CacheFirst } from 'workbox-routing';
import { BackgroundSyncPlugin } from 'workbox-background-sync';

// Take control immediately
clientsClaim();

// Precache all assets generated by the build
precacheAndRoute(self.__WB_MANIFEST);

// App shell
const handler = createHandlerBoundToURL('index.html');
const navRoute = new NavigationRoute(handler);
registerRoute(navRoute);

// API caching
registerRoute(
  /\/api\/(?:reports|checkpoints\/.*\/wait-times)/,
  new NetworkOnly({
    plugins: [
      new BackgroundSyncPlugin('wait-time-reports', {
        maxRetentionTime: 24 * 60, // Retry for 24 hours
      }),
    ],
  }),
  'POST'
);

registerRoute(
  /\/api\/.*/,
  new NetworkFirst({
    cacheName: 'api-cache',
  }),
  'GET'
);

registerRoute(
  /\.(?:png|jpg|svg|css|js)$/,
  new CacheFirst({
    cacheName: 'static-assets',
  })
);

// Cleanup outdated caches
cleanupOutdatedCaches();

// Push notification handler
self.addEventListener('push', (event) => {
  let data = { title: 'Flyby Alert', body: 'New wait time update', icon: '/icon-192.png' };

  try {
    if (event.data) {
      data = event.data.json();
    }
  } catch (err) {
    // If data is not JSON, use as plain text
    data.body = event.data?.text() || data.body;
  }

  const options = {
    body: data.body,
    icon: data.icon || '/icon-192.png',
    badge: '/icon-192.png',
    vibrate: [100, 50, 100],
    data: {
      dateOfArrival: Date.now(),
      primaryKey: data.primaryKey || 1,
      url: data.url || '/',
    },
    actions: [
      { action: 'explore', title: 'View Checkpoint' },
      { action: 'close', title: 'Close' },
    ],
  };

  event.waitUntil(
    self.registration.showNotification(data.title || 'Flyby', options)
  );
});

// Handle notification click
self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  if (event.action === 'explore') {
    const urlToOpen = event.notification.data?.url || '/';
    event.waitUntil(
      self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
        for (const client of clientList) {
          if (client.url === urlToOpen && 'focus' in client) {
            return client.focus();
          }
        }
        if (self.clients.openWindow) {
          return self.clients.openWindow(urlToOpen);
        }
      })
    );
  } else {
    // Default: open the app
    const urlToOpen = event.notification.data?.url || '/';
    event.waitUntil(
      self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
        for (const client of clientList) {
          if (client.url === urlToOpen && 'focus' in client) {
            return client.focus();
          }
        }
        if (self.clients.openWindow) {
          return self.clients.openWindow(urlToOpen);
        }
      })
    );
  }
});

// Handle skip waiting message from client
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// Export for workbox
export {};